/**
 * Pila de monedas de los capítulos de pago. El dibujo de 14×15 va en un marco
 * de 17×17 (1,21 de aire por lado), como en las tarjetas del diseño.
 */
export const CoinStackIcon = ({ size = 16, className }: IconProps) => {
  const gradientId = `coin-stack-${useId().replace(/[^a-zA-Z0-9_-]/g, '')}`;
  return (
    <svg width={size} height={size} viewBox="-1.21429 -1.21429 17 17" fill="none" className={className} aria-hidden="true">
      {COIN_PATHS.map((d, index) => <path key={d} d={d} fill={`url(#${gradientId}-${index})`} />)}
      <defs>
        {COIN_GRADIENTS.map(({ x1, y1, x2, y2, from, to }, index) => (
          <linearGradient key={index} id={`${gradientId}-${index}`} x1={x1} y1={y1} x2={x2} y2={y2} gradientUnits="userSpaceOnUse">
            <stop stopColor={from} />
            <stop offset="1" stopColor={to} />
          </linearGradient>
        ))}
      </defs>
    </svg>
  );
};

