export type FooterSocialNetwork = keyof typeof FOOTER_SOCIAL_GLYPHS;

/** Una red de la fila del pie, dibujada al alto de fila indicado. */
export const FooterSocialGlyph = ({ network, height, className }: { network: FooterSocialNetwork; height: number; className?: string }) => {
  const { x: left, width, path } = FOOTER_SOCIAL_GLYPHS[network];
  return (
    <svg width={(width * height) / FOOTER_SOCIAL_ROW_HEIGHT} height={height} viewBox={`${left} 0 ${width} ${FOOTER_SOCIAL_ROW_HEIGHT}`} fill="none" className={className} aria-hidden="true">
      <path d={path} fill="currentColor" />
    </svg>
  );
};
